//! Gold: `regions` scoring is 1:1 with the live `harness/electronics/regions.py`.
//!
//! `tests/fixtures/gold/regions_v1.json` was generated by
//! `scripts/gold_regions.py` — kernel cases call the pure structural-discovery
//! readers over table rows and page-evidence mappings (`None`/empty cells as
//! `extract()` returns them). The pymupdf render half (`render_*`,
//! `pdftotext_layout_page`) is process I/O and stays Python-side.
//!
//! The cases pin the traps the scorer exists for: register maps and ordering
//! guides vetoed (a real pin header overrides the register veto),
//! `PHYSICAL_ID` accepting large BGA balls (`AA10`), physical identifier
//! columns needing 3+ hits at 45% density, a missing pin-definition header
//! dropping the score to 0, parametric tables needing a parameter header
//! AND 2+ value-role headers (`SYMBOL` counts as a parameter header),
//! text regions bounding only visible evidence and requiring the
//! capability's signal, and `printed_package_mentions` deduplicating
//! case-insensitively in first-seen order.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::path::PathBuf;

use serde_json::Value;

use dw_recon::regions::{
    parametric_table_score, pin_table_score, printed_package_mentions,
    structural_parametric_regions, structural_pin_regions, structural_text_regions,
};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/regions_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

fn rows_of(v: &Value) -> Vec<Vec<Value>> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|row| row.as_array().unwrap().clone())
        .collect()
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];
        let got: Value = match case["kind"].as_str().unwrap() {
            "pin_table_score" => {
                let (score, reasons) = pin_table_score(&rows_of(&input["rows"]));
                serde_json::json!([score, reasons])
            }
            "parametric_table_score" => {
                let (score, reasons) = parametric_table_score(&rows_of(&input["rows"]));
                serde_json::json!([score, reasons])
            }
            "structural_pin_regions" => {
                serde_json::to_value(structural_pin_regions(&input["page_evidence"], 5)).unwrap()
            }
            "structural_parametric_regions" => {
                serde_json::to_value(structural_parametric_regions(&input["page_evidence"], 5))
                    .unwrap()
            }
            "structural_text_regions" => serde_json::to_value(
                structural_text_regions(
                    &input["page_evidence"],
                    input["capability"].as_str().unwrap(),
                )
                .unwrap(),
            )
            .unwrap(),
            "printed_package_mentions" => {
                serde_json::to_value(printed_package_mentions(&input["page_evidence"])).unwrap()
            }
            other => panic!("unknown gold case kind {other}"),
        };
        assert_eq!(got, case["expected"], "case {name}");
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
